#: MURaM magnetic corrections Δw (added to w), [M/H] = 0 MURaM stars; linear in
#: Teff, clamped outside 3196-6807 K, applied at all log g and [M/H]
#: (an extrapolation); MURaM ratios held constant below mu = 0.1.
_CORR_TEFF = np.array([3196.0, 3518.0, 3707.0, 4543.0, 5240.0, 5778.0, 6807.0])
_CORR = {
    "ssd": [[1.480000e-04, -7.000000e-06, -4.400000e-05, -8.000000e-06], [6.610000e-04, 8.310000e-04, -1.310000e-03, -9.270000e-04], [-1.770000e-03, 1.870000e-04, -7.760000e-04, -3.546000e-03], [-6.500000e-05, -2.670000e-04, -7.250000e-04, -5.640000e-04], [-1.265000e-03, -1.366000e-03, 4.910000e-04, 1.403000e-03], [-4.145000e-03, 1.126000e-03, 2.097000e-03, -3.300000e-04], [-5.346000e-03, 1.108600e-02, 4.839000e-03, -1.127800e-02]],
    "B100G": [[-7.690000e-04, 5.870000e-04, 1.150000e-04, -1.525000e-03], [-2.400000e-05, 1.106000e-03, 1.700000e-04, -1.804000e-03], [-3.766000e-03, -3.770000e-04, 4.469000e-03, -2.772000e-03], [-2.392000e-03, -4.306000e-03, 2.771000e-03, 2.527000e-03], [-6.672000e-03, -1.129700e-02, 7.615000e-03, 5.199000e-03], [-1.324000e-02, -7.892000e-03, 1.260800e-02, -6.420000e-04], [-2.309400e-02, -3.557000e-03, 3.066600e-02, -1.033600e-02]],
    "B200G": [[-1.396000e-03, 1.796000e-03, -4.810000e-04, -3.818000e-03], [-1.208000e-03, 1.848000e-03, 6.000000e-06, -4.661000e-03], [-8.134000e-03, 2.160000e-04, 6.212000e-03, -6.180000e-03], [-8.299000e-03, -7.794000e-03, 7.816000e-03, 2.757000e-03], [-1.858500e-02, -1.609300e-02, 1.722500e-02, 2.598000e-03], [-2.471400e-02, -1.828000e-02, 2.445400e-02, 1.871000e-03], [-4.525700e-02, -1.308100e-02, 5.790000e-02, -2.433900e-02]],
    "B300G": [[-1.914000e-03, 2.409000e-03, -1.176000e-03, -5.930000e-03], [-2.788000e-03, 4.088000e-03, -3.740000e-04, -6.927000e-03], [-1.043500e-02, 1.259000e-03, 5.894000e-03, -9.496000e-03], [-1.575800e-02, -1.115500e-02, 1.174900e-02, 3.488000e-03], [-3.151000e-02, -2.394900e-02, 2.707900e-02, 3.916000e-03], [-3.993000e-02, -1.890300e-02, 4.010600e-02, -1.294600e-02], [-7.782000e-02, -1.347000e-02, 9.897800e-02, -6.144900e-02]],
}


def _unpack(s, shape, dtype):
    return np.frombuffer(zlib.decompress(base64.b64decode(s)), dtype).astype(float).reshape(shape)


_X = _unpack(_GRID, (_N, 3), "<f8") / SCALE
_Y = _unpack(_DATA, (_N, 6), "<f4")
_LIN = LinearNDInterpolator(_X, _Y)
_NEAR = None


def _pole(mu, e):
    return ((mu * mu + e) ** -2 - (1 + e) ** -2) / (e ** -2 - (1 + e) ** -2)


def _basis():
    """Rows: S1..S4 on (1 - mu^4, (1 - mu^2)^2, P_e0, P_e1); with g = dI/dx,
    S3: I(0) = 0, g(1) = g'(1) = g''(1) = 0; S4: I(0) = 0, g(1) = g'(1) = g''(0) = 0."""
    (e0, e1), (a0, a1) = EPS, (1 / (e ** -2 - (1 + e) ** -2) for e in EPS)
    g = lambda x: [2 * x, 2 * (1 - x), 2 * a0 * (x + e0) ** -3, 2 * a1 * (x + e1) ** -3]
    g1 = lambda x: [2.0, -2.0, -6 * a0 * (x + e0) ** -4, -6 * a1 * (x + e1) ** -4]
    g2 = lambda x: [0.0, 0.0, 24 * a0 * (x + e0) ** -5, 24 * a1 * (x + e1) ** -5]
    S3 = np.linalg.solve([[1.0] * 4, g(1.0), g1(1.0), g2(1.0)], [1.0, 0, 0, 0])
    S4 = np.linalg.solve([[1.0] * 4, g(1.0), g1(1.0), g2(0.0)], [1.0, 0, 0, 0])
    return np.array([[0.5, 0.5, 0, 0], [0, 1.0, 0, 0], S3, S4])


BASIS = _basis()


def shapes(mu):
    """S_k(mu), shape (len(mu), 4)."""
    mu = np.asarray(mu, float)
    T = np.stack([1 - mu ** 4, (1 - mu ** 2) ** 2, _pole(mu, EPS[0]), _pole(mu, EPS[1])], axis=-1)
    return T @ BASIS.T


def from_q(q):
    """Weights from sampling coordinates q in [0, 1]^4 (vectorised over rows)."""
    q = np.asarray(q, float)
    s, a, b = q[..., 0] ** 0.25, q[..., 1] ** (1 / 3), q[..., 2] ** 0.5
    return np.stack([s * (1 - a), s * a * (1 - b), s * a * b * (1 - q[..., 3]), s * a * b * q[..., 3]], -1)


def to_q(w):
    """Sampling coordinates of one set of weights (outside [0, 1] if outside the region)."""
    w = np.asarray(w, float)
    s = w.sum()
    if s == 0:
        return (0.0, 0.0, 0.0, 0.0)
    f = w / s
    r1 = 1 - f[0]
    r2 = 1 - f[1] / r1 if r1 != 0 else 0.0
    f34 = f[2] + f[3]
    q = np.array([np.sign(s) * abs(s) ** 4, np.sign(r1) * abs(r1) ** 3,
                  r2 * r2 if r2 >= 0 else r2, f[3] / f34 if f34 != 0 else 0.0])
    q = np.where((q < 0) & (q > -1e-9), 0.0, q)            # rounding noise onto the bound
    return tuple(float(v) for v in np.where((q > 1) & (q < 1 + 1e-9), 1.0, q))


def intensity(w, mu):
    """I(mu)/I(1) for hybrid4 weights w."""
    return 1 - shapes(mu) @ np.asarray(w, float)


def is_physical(w, n=2001):
    """Positive and non-increasing towards the limb on a dense grid."""
    I = intensity(w, np.linspace(0.0, 1.0, n))
    return bool(I[0] >= -1e-10 and np.all(np.diff(I) >= -1e-10))


def coefficients(teff, logg, mh, extrapolate=False, correction=None):
    """Interpolated hybrid4 weights at (Teff [K], log g [cgs], [M/H]).

    extrapolate=True uses the nearest model outside the grid (else ValueError).
    Returns dict(w, q, physical, mu_cri, lc_ppm, inside, correction)."""
    global _NEAR
    x = np.array([[teff, logg, mh]]) / SCALE
    y = _LIN(x)[0]
    inside = bool(np.all(np.isfinite(y)))
    if not inside:
        if not extrapolate:
            raise ValueError(f"({teff}, {logg}, {mh}) is outside the {GRID} grid; "
                             "pass extrapolate=True to use the nearest model")
        if _NEAR is None:
            _NEAR = NearestNDInterpolator(_X, _Y)
        y = _NEAR(x)[0]
    w = y[:4].copy()
    if correction is not None:
        if correction not in _CORR:
            raise ValueError(f"correction must be one of {tuple(_CORR)}")
        if not _CORR_TEFF[0] <= teff <= _CORR_TEFF[-1]:
            warnings.warn("Teff outside the MURaM range: correction clamped", stacklevel=2)
        D = np.array(_CORR[correction])
        w = w + np.array([np.interp(teff, _CORR_TEFF, D[:, k]) for k in range(4)])
    return dict(w=tuple(float(v) for v in w), q=to_q(w), physical=is_physical(w), mu_cri=float(y[4]),
                lc_ppm=float(y[5]), inside=inside, correction=correction)


if __name__ == "__main__":
    import sys
    t, g, m = (float(v) for v in sys.argv[1:4]) if len(sys.argv) >= 4 else (5600.0, 4.4, 0.0)
    r = coefficients(t, g, m, extrapolate=True)
    print(f"hybrid4 {GRID} {BAND} Teff={t:g} logg={g:g} [M/H]={m:+g}: w =",
          " ".join(f"{v:.6f}" for v in r["w"]), "q =", " ".join(f"{v:.6f}" for v in r["q"]),
          "physical" if r["physical"] else "UNPHYSICAL",
          "" if r["inside"] else "(nearest model; outside grid)")
